package com.quizmaster.servlet;
import com.quizmaster.dao.*;import com.quizmaster.model.*;import com.quizmaster.util.*;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;import java.util.*;
@WebServlet(urlPatterns={"/student/dashboard","/student/history","/student/start","/student/attempt","/student/submit","/student/result"})public class StudentServlet extends HttpServlet{
 private final QuizDAO quizzes=new QuizDAO();private final QuestionDAO questions=new QuestionDAO();private final AttemptDAO attempts=new AttemptDAO();
 protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{User user=(User)r.getSession().getAttribute("user");String path=r.getServletPath();try{switch(path){case "/student/dashboard"-> {r.setAttribute("quizzes",quizzes.all());r.setAttribute("history",attempts.history(user.getId(),null));view(r,p,"dashboard");}case "/student/history"->{r.setAttribute("history",attempts.history(user.getId(),null));view(r,p,"history");}case "/student/attempt"->{long id=WebUtil.positive(r.getParameter("id"));Attempt a=attempts.getForUser(id,user.getId());if(a==null){p.sendError(404);return;}if(!a.status().equals("IN_PROGRESS")){p.sendRedirect(r.getContextPath()+"/student/result?id="+id);return;}Quiz q=quizzes.get(a.quizId());if(q==null){p.sendError(404);return;}r.setAttribute("quiz",q);r.setAttribute("attempt",a);r.setAttribute("questions",questions.list(q.id(),true));r.setAttribute("deadline",a.started().getTime()+q.duration()*60000L);view(r,p,"attempt");}case "/student/result"->{long id=WebUtil.positive(r.getParameter("id"));Attempt a=attempts.getForUser(id,user.getId());if(a==null||a.status().equals("IN_PROGRESS")){p.sendError(404);return;}r.setAttribute("attempt",a);r.setAttribute("quiz",quizzes.get(a.quizId()));r.setAttribute("details",attempts.details(id,user.getId()));view(r,p,"result");}default ->p.sendError(405);}}catch(SQLException e){getServletContext().log("Student read failed",e);p.sendError(500);}}
 protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");if(!WebUtil.valid(r)){p.sendError(403);return;}User user=(User)r.getSession().getAttribute("user");try{if(r.getServletPath().equals("/student/start")){long quiz=WebUtil.positive(r.getParameter("quiz"));if(quizzes.get(quiz)==null||questions.list(quiz,false).isEmpty()){p.sendError(400,"Quiz unavailable or empty");return;}try{Attempt a=attempts.start(user.getId(),quiz);p.sendRedirect(r.getContextPath()+"/student/attempt?id="+a.id());}catch(SQLException duplicate){getServletContext().log("Quiz already attempted",duplicate);p.sendRedirect(r.getContextPath()+"/student/history");}}else if(r.getServletPath().equals("/student/submit")){long id=WebUtil.positive(r.getParameter("id"));Attempt a=attempts.getForUser(id,user.getId());if(a==null){p.sendError(404);return;}Map<Long,String> answers=new HashMap<>();for(Question q:questions.list(a.quizId(),false)){String choice=r.getParameter("q_"+q.id());if(choice!=null)answers.put(q.id(),choice);}attempts.submit(id,user.getId(),answers,5);p.sendRedirect(r.getContextPath()+"/student/result?id="+id);}else p.sendError(405);}catch(IllegalArgumentException e){p.sendError(409,"Attempt already completed");}catch(SQLException e){getServletContext().log("Attempt failure",e);p.sendError(500,"Database error");}}
 private void view(HttpServletRequest r,HttpServletResponse p,String name)throws ServletException,IOException{r.getRequestDispatcher("/WEB-INF/views/student/"+name+".jsp").forward(r,p);}
}
